display:flex;justify-content:flex-end;gap:12px;margin-top:32px;padding-top:24px;border-top:1px solid var(--line)}.notice{display:none;margin-bottom:20px;border-radius:14px;padding:14px 16px;font-weight:600}.notice.show{display:block}.notice.error{background:#fff0ef;color:var(--danger)}.success-card{display:none;text-align:center;padding:38px 20px}.success-card.show{display:block}.success-icon{width:64px;height:64px;border-radius:50%;display:grid;place-items:center;margin:0 auto 18px;background:#dff8ef;color:#087653;font-size:28px}.success-card h2{font:700 26px 'Plus Jakarta Sans';margin:0 0 8px}.request-code{display:inline-block;background:#eef4ff;color:var(--blue-dark);font-weight:800;letter-spacing:.08em;border-radius:10px;padding:10px 14px;margin:12px 0 20px}.footer-note{text-align:center;color:var(--muted);font-size:13px;margin-top:20px}@media(max-width:700px){.hero-inner{padding-top:18px;padding-bottom:66px}.eyebrow{margin-top:58px}.hero-copy{font-size:16px}.form-card{padding:22px 18px;border-radius:18px}.form-header{display:block}.step-pill{display:inline-block;margin-top:16px}.grid{grid-template-columns:1fr}.full{grid-column:auto}.lookup{display:block}.lookup .btn{width:100%;margin-top:10px}.form-actions{display:grid;grid-template-columns:1fr}.form-actions .btn{width:100%}}
</style><style>.input-group{display:flex;align-items:stretch;flex:1;min-width:0;height:48px}.input-group .form-control{border-radius:0 12px 12px 0;min-width:0;height:48px}.lookup .input-group{flex:1;min-width:0;height:48px}.lookup .input-group .select2-container{width:190px!important;flex:0 0 190px;height:48px}.lookup .input-group select.country-select.select2-hidden-accessible{display:none!important}.lookup .input-group .select2-container--default .select2-selection--single{height:48px;border:1px solid var(--line);border-right:0;border-radius:12px 0 0 12px;background:#eef4f8;display:flex;align-items:center}.lookup .input-group .select2-container--default .select2-selection--single .select2-selection__rendered{color:var(--ink);font:600 14px/48px 'DM Sans';padding:0 30px 0 12px}.lookup .input-group .select2-container--default .select2-selection--single .select2-selection__arrow{height:46px;right:7px}.lookup .input-group:focus-within .select2-selection--single,.lookup .input-group:focus-within .form-control{border-color:var(--blue)}.lookup .input-group:focus-within{box-shadow:0 0 0 4px rgba(20,100,244,.12);border-radius:12px}.lookup .input-group .form-control:focus{box-shadow:none}.country-select{width:190px}.select2-dropdown{border:1px solid var(--line);border-radius:12px;overflow:hidden;box-shadow:0 16px 30px rgba(18,38,58,.14)}.select2-search--dropdown{padding:10px}.select2-search--dropdown .select2-search__field{border:1px solid var(--line);border-radius:8px;padding:8px 10px;font:14px 'DM Sans'}.select2-results__option{padding:9px 12px;font-size:14px}.select2-container--default .select2-results__option--highlighted[aria-selected]{background:var(--blue)}@media(max-width:700px){.lookup .input-group{width:100%;height:48px}.lookup .input-group .select2-container{width:142px!important;flex-basis:142px}.lookup .input-group .select2-container--default .select2-selection--single .select2-selection__rendered{font-size:12px;padding-left:8px}.lookup .input-group .select2-container--default .select2-selection--single .select2-selection__arrow{right:3px}.lookup .input-group .form-control{font-size:15px}}</style></head>
<body><div class="page-shell"><header class="hero"><div class="hero-inner"><a class="brand" href="{{ url('/') }}"><img src="{{ asset('files/img/namikulo.png') }}" alt="">NAMIKULO</a><div class="eyebrow">Request task online</div><h1>Wujudkan task yang ingin kamu selesaikan.</h1><p class="hero-copy">Ceritakan kebutuhanmu dengan detail. Tim Namikulo akan meninjau request dan menghubungimu untuk langkah berikutnya.</p></div></header><main class="main"><section class="form-card"><div id="request-form-wrap"><div class="form-header"><div><h2>Mulai request task</h2><p>Isi informasi di bawah, hanya butuh beberapa menit.</p></div><span class="step-pill">Aman &amp; tanpa login</span></div><div id="notice" class="notice" role="alert"></div><form id="request-form"><div class="section-label">Kenali kamu dulu</div><div class="grid"><div class="full"><label for="handphone">Nomor WhatsApp <span class="required">*</span></label><div class="lookup"><input id="handphone" name="handphone" class="form-control" type="tel" inputmode="tel" autocomplete="tel" placeholder="Contoh: 0812 3456 7890" required><button class="btn btn-soft" type="button" id="lookup-btn">Cari data</button></div><p class="helper">Kami gunakan nomor ini untuk menemukan data client dan menghubungimu.</p><div id="client-found" class="client-found"></div><div id="client-fields" class="client-fields"><strong>Data baru ditemukan belum ada</strong><p class="helper">Lengkapi data singkat ini agar kami bisa menyimpan request-mu.</p><div class="grid" style="margin-top:16px"><div><label for="customer">Nama lengkap <span class="required">*</span></label><input id="customer" name="customer" class="form-control" autocomplete="name"></div><div><label for="jk">Jenis kelamin <span class="required">*</span></label><select id="jk" name="jk" class="form-control"><option value="">Pilih jenis kelamin</option><option value="Laki-laki">Laki-laki</option><option value="Perempuan">Perempuan</option></select></div><div class="full"><label for="asal">Asal / domisili</label><input id="asal" name="asal" class="form-control" placeholder="Contoh: Kuala Lumpur"></div></div></div></div></div><div class="section-label full">Detail request</div><div><label for="category_id">Kategori task <span class="required">*</span></label><select id="category_id" name="category_id" class="form-control" required><option value="">Pilih kategori</option>@foreach ($categories as $category)<option value="{{ $category->id }}" data-type="{{ $category->tipe }}">{{ $category->nama }}</option>@endforeach</select></div><div><label for="order">Kapan mulai diproses? <span class="required">*</span></label><input id="order" name="order" class="form-control" type="date" value="{{ date('Y-m-d') }}" required></div><div><label for="deadline">Target selesai</label><input id="deadline" name="deadline" class="form-control" type="date"><p class="helper">Opsional, isi jika punya target waktu.</p></div><div class="full"><label for="task">Ceritakan task yang kamu butuhkan <span class="required">*</span></label><textarea id="task" name="task" class="form-control" rows="4" placeholder="Jelaskan kebutuhan, output yang diharapkan, atau hal penting lainnya..." required></textarea></div><div id="academic-fields" class="academic-fields full"><div class="section-label" style="margin-top:0">Informasi akademik</div><div class="grid"><div><label for="prodi">Program studi <span class="required">*</span></label><input id="prodi" name="prodi" class="form-control"></div><div id="continuation-wrap" class="switch-row"><input id="is_lanjutan_metopen" name="is_lanjutan_metopen" type="checkbox" value="1"><label for="is_lanjutan_metopen" style="margin:0">Ini lanjutan dari Metopen</label></div><div class="full"><label for="judul">Judul <span class="required">*</span></label><textarea id="judul" name="judul" class="form-control" rows="2"></textarea></div><div class="full"><label for="keterangan">Keterangan tambahan</label><textarea id="keterangan" name="keterangan" class="form-control" rows="3"></textarea></div></div></div></div><div class="form-actions"><button class="btn btn-soft" type="reset">Reset</button><button class="btn btn-primary" id="submit-btn" type="submit">Kirim request</button></div></form></div><div id="success-card" class="success-card" aria-live="polite"><div class="success-icon">✓</div><h2>Request berhasil dikirim</h2><p>Terima kasih. Simpan kode request ini untuk referensi saat kami menghubungimu.</p><div id="request-code" class="request-code"></div><br><button class="btn btn-soft" type="button" onclick="window.location.reload()">Buat request lain</button></div></section><p class="footer-note">Namikulo · Kami akan menghubungi kamu melalui WhatsApp setelah request ditinjau.</p></main></div>
<script>
const countryOptions=@json($countries),phoneInput=document.getElementById('handphone'),lookupRow=phoneInput.closest('.lookup'),phoneGroup=document.createElement('div'),countrySelect=document.createElement('select');phoneInput.placeholder='81398238734';phoneGroup.className='input-group';countrySelect.id='handphone_country';countrySelect.name='handphone_country';countrySelect.className='country-select';countrySelect.setAttribute('aria-label','Negara nomor telepon');countryOptions.forEach(function(country){const option=document.createElement('option');option.value=country.code;option.textContent=country.name+' '+country.dial_code;option.dataset.countryName=country.name;option.dataset.dialCode=country.dial_code;if(country.code==='ID')option.selected=true;countrySelect.appendChild(option)});phoneGroup.appendChild(countrySelect);lookupRow.insertBefore(phoneGroup,lookupRow.querySelector('#lookup-btn'));phoneGroup.appendChild(phoneInput);
const form=document.getElementById('request-form'),category=document.getElementById('category_id'),academic=document.getElementById('academic-fields'),continuation=document.getElementById('continuation-wrap'),clientFields=document.getElementById('client-fields'),clientFound=document.getElementById('client-found'),notice=document.getElementById('notice'),title=document.getElementById('judul'),titleField=title.closest('.full'),titlePendingWrap=document.createElement('div');titlePendingWrap.className='switch-row full title-pending-wrap';titlePendingWrap.style.display='none';titlePendingWrap.innerHTML='<input id="belum_memiliki_judul" name="belum_memiliki_judul" type="checkbox" value="1"><label for="belum_memiliki_judul" style="margin:0">Saya belum memiliki judul penelitian</label>';titleField.parentNode.insertBefore(titlePendingWrap,titleField);
const sweetAlertReady=new Promise(function(resolve){const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/sweetalert2@11.15.10/dist/sweetalert2.all.min.js';script.onload=resolve;script.onerror=resolve;document.head.appendChild(script)});
async function showRequestAlert(options){await sweetAlertReady;if(window.Swal)return Swal.fire(options);window.alert((options.title?options.title+'\n':'')+(options.text||''));return null}
function syncAcademic(){const type=category.options[category.selectedIndex]?.dataset.type||'',show=['metopen','artikel_ilmiah'].includes(type),pending=type==='metopen'&&document.getElementById('belum_memiliki_judul').checked;academic.classList.toggle('show',show);continuation.style.display=type==='artikel_ilmiah'?'flex':'none';titlePendingWrap.style.display=type==='metopen'?'flex':'none';document.getElementById('prodi').required=show;title.required=show&&!pending;title.disabled=pending;titleField.querySelector('.required').style.display=pending?'none':'';if(type!=='metopen')document.getElementById('belum_memiliki_judul').checked=false}category.addEventListener('change',syncAcademic);document.getElementById('belum_memiliki_judul').addEventListener('change',syncAcademic);
document.getElementById('lookup-btn').addEventListener('click',async()=>{const phone=document.getElementById('handphone').value.trim();if(!phone)return;const button=document.getElementById('lookup-btn');button.disabled=true;button.textContent='Mencari...';try{const res=await fetch('{{ url('request-task/client-lookup') }}?handphone='+encodeURIComponent(phone)+'&handphone_country='+encodeURIComponent(document.getElementById('handphone_country').value));const data=await res.json();clientFound.classList.add('show');if(data.found){clientFound.textContent='Data client ditemukan: '+data.client.customer+'. Kamu bisa langsung melanjutkan request.';clientFields.classList.remove('show');let id=document.getElementById('client_id');if(!id){id=document.createElement('input');id.type='hidden';id.name='client_id';id.id='client_id';form.appendChild(id)}id.value=data.client.id}else{clientFound.textContent='Data belum ditemukan. Lengkapi data singkat di bawah ini untuk membuat profil client.';clientFields.classList.add('show');const id=document.getElementById('client_id');if(id)id.remove()}}catch(e){clientFound.textContent='Belum bisa mencari data. Kamu tetap bisa melanjutkan dengan mengisi data client baru.';clientFields.classList.add('show')}button.disabled=false;button.textContent='Cari data'});
form.addEventListener('submit',async e=>{e.preventDefault();const button=document.getElementById('submit-btn');button.disabled=true;button.textContent='Mengirim...';try{const res=await fetch('{{ url('request-task') }}',{method:'POST',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content,'Accept':'application/json'},body:new FormData(form)});const contentType=res.headers.get('content-type')||'';const data=contentType.includes('application/json')?await res.json():{};if(!res.ok){const errors=data.errors?Object.values(data.errors).flat().join('\n'):data.message||'Request gagal dikirim. Periksa kembali isian form.';throw new Error(errors)}if(data.status!==undefined&&Number(data.status)!==1)throw new Error(data.msg||'Request gagal dikirim.');await showRequestAlert({icon:'success',title:'Request berhasil dikirim',text:'Simpan kode request untuk referensi saat kami menghubungimu.',footer:data.kode_request?'<strong>Kode: '+data.kode_request+'</strong>':'',confirmButtonText:'Selesai',confirmButtonColor:'#1464f4'});form.reset();clientFound.classList.remove('show');clientFields.classList.remove('show');const clientId=document.getElementById('client_id');if(clientId)clientId.remove();notice.className='notice';button.disabled=false;button.textContent='Kirim request';syncAcademic()}catch(err){await showRequestAlert({icon:'error',title:'Request gagal dikirim',text:err.message||'Terjadi kesalahan. Silakan coba lagi.',confirmButtonText:'Coba lagi',confirmButtonColor:'#1464f4'});button.disabled=false;button.textContent='Kirim request'}});syncAcademic();
</script><script src="https://code.jquery.com/jquery-3.7.1.min.js"></script><script src="https://cdn.jsdelivr.net/npm/select2@4.1.0-rc.0/dist/js/select2.min.js"></script><script>$(function(){var flagUrl=function(code){return 'https://flagcdn.com/w40/'+String(code).toLowerCase()+'.png'};var dialCode=function(data){return data.element&&data.element.dataset.dialCode?data.element.dataset.dialCode:data.text};var flagSelection=function(data){if(!data.id)return data.text;var result=$('<span class="country-selected"></span>');$('<img>',{src:flagUrl(data.id),alt:'',title:data.element.dataset.countryName,class:'country-flag country-flag-selected',width:28,height:18}).appendTo(result);$('<span></span>').text(dialCode(data)).appendTo(result);return result};var flagResult=function(data){if(!data.id)return data.text;var result=$('<span class="country-option"></span>');$('<img>',{src:flagUrl(data.id),alt:'',class:'country-flag',width:24,height:16}).appendTo(result);$('<span></span>').text(dialCode(data)).appendTo(result);return result};$('#handphone_country').select2({width:'190px',templateSelection:flagSelection,templateResult:flagResult,escapeMarkup:function(markup){return markup},language:{searching:function(){return 'Mencari...'},noResults:function(){return 'Negara tidak ditemukan'}}});});</script></body></html>
<style>
    @import url('https://fonts.googleapis.com/css2?family=Poppins:wght@600;700;800&display=swap');
